def generate_vars_2(modulo: int):
    placements = generate_vars_1(modulo)
    rounds = [i+1 for i in range(50)]
    upgrades = [i for i in range(4)]

    return [rounds, placements, upgrades]


def generate_tower_upgrade_costs() -> Dict[Tuple[str, int], int]:
    """
    Generates a dictionary with cumulative costs of building a tower with upgrades.
    :returns: a Dict with cumulative costs of building a tower with upgrades.
    """
    out = {}
    tower_data = create_towers_dataframe()
    upgrade_columns = ['cost', 'cumulative_cost_upgrade_1', 'cumulative_cost_upgrade_2', 'cumulative_cost_upgrade_12']
    for tower in tower_data.index:
        for upgrade in range(4):
            out[tower, upgrade] = tower_data.loc[tower, upgrade_columns[upgrade]]

    return out

def generate_money_constraints_rhs() -> Dict[int, int]:
    """
    Determines the amount of money the player will have at the beginning of round 
    round_nr (best case).
    :returns: Dict, of form {round_nr: money}
    """
    out = {}
    for i in range(50):
        out[i+1] = get_money_constraint_rhs(i)
    return out

