def generate_var_label_sets(modulo: int) -> Tuple[Tuple]:
    """
    
    """
    placements_nonsuper = generate_all_tower_placements(False)
    placements_super = generate_all_tower_placements(True)

    placements_nonsuper_mod = filter_point_set_module(placements_nonsuper, modulo)
    placements_super_mod = filter_point_set_module(placements_super, modulo)

    monkey_types_nonsuper = ['Dart', 'Tack', 'Bomb', 'Ice']
    monkey_types_super = 'SuperMonkey'

    upgrade_vals_nonsuper = (0,1,2)
    upgrade_vals_super = (0,1)

    return ((placements_nonsuper_mod, monkey_types_nonsuper, upgrade_vals_nonsuper), (placements_super_mod, monkey_types_super, upgrade_vals_super))

